extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var menu := await instantiate_main_scene()
	if not check("main_scene_loaded", menu != null, "La scena principale deve essere impostata e caricarsi senza errori"):
		return
	var play_button := find_by_name(menu, "PlayButton") as BaseButton
	var quit_button := find_by_name(menu, "QuitButton") as BaseButton
	if not check("buttons_exist", play_button != null and quit_button != null, "I pulsanti PlayButton e QuitButton devono essere presenti nella scena"):
		return
	var conns := quit_button.pressed.get_connections()
	check("quit_connected", conns.size() > 0, "Il segnale pressed di QuitButton deve essere collegato a una funzione")
	await click_button(play_button)
	await wait_frames(2)
	check("scene_changed_to_basket", current_scene_path() == "res://basket.tscn" or (get_tree().current_scene != null and get_tree().current_scene.name == "Basket"), "Premendo PlayButton la scena attiva deve diventare res://basket.tscn")

